<main class="section"><div class="section-head"><div><span class="eyebrow">Verkäuferinnenakte #<?=$seller['id']?></span><h1><?=App\Core\View::e($seller['first_name'].' '.$seller['last_name'])?></h1><p class="muted"><?=App\Core\View::e($seller['email'])?> · <?= $seller['email_verified_at']?'E-Mail verifiziert':'E-Mail nicht verifiziert' ?></p></div><a class="btn" href="/admin/verkaeuferinnen">Liste</a></div>
<section class="card admin-form"><h2>Stammdaten bearbeiten</h2><form method="post" action="/admin/verkaeuferinnen/<?=$seller['id']?>" class="form-grid"><?=App\Core\Csrf::field()?><label>Vorname<input name="first_name" value="<?=App\Core\View::e($seller['first_name'])?>" required></label><label>Nachname<input name="last_name" value="<?=App\Core\View::e($seller['last_name'])?>" required></label><label>Geburtsdatum<input name="birth_date" type="date" value="<?=App\Core\View::e($seller['birth_date'])?>" required></label><label>Telefon<input name="phone" value="<?=App\Core\View::e($seller['phone'])?>" required></label><label class="full">Straße<input name="street" value="<?=App\Core\View::e($seller['street'])?>" required></label><label>PLZ<input name="postal_code" value="<?=App\Core\View::e($seller['postal_code'])?>" required></label><label>Ort<input name="city" value="<?=App\Core\View::e($seller['city'])?>" required></label><label class="full">E-Mail<input name="email" type="email" value="<?=App\Core\View::e($seller['email'])?>" required></label><label class="full">Admin-Passwort <small>(nur nötig bei Änderung von E-Mail oder Geburtsdatum)</small><input name="admin_password" type="password"></label><button class="btn primary full">Änderungen speichern</button></form></section>
<div class="dash-grid"><div class="card dash-card"><span>Verfügbar</span><strong><?=number_format((float)($wallet['balance_available']??0),2,',','.')?> €</strong></div><div class="card dash-card"><span>Vorgemerkt</span><strong><?=number_format((float)($wallet['balance_reserved']??0),2,',','.')?> €</strong></div><div class="card dash-card"><span>In Prüfung</span><strong><?=number_format((float)($wallet['balance_in_review']??0),2,',','.')?> €</strong></div></div>
<h2>Aufträge</h2><div class="worklist"><?php foreach($orders as $o):?><a class="work-row" href="/admin/auftraege/<?=$o['id']?>"><div><b>#<?=App\Core\View::e($o['order_number'])?></b><span><?=App\Core\View::e($o['status'])?> · <?=App\Core\View::e($o['phase'])?></span></div><strong><?=number_format((float)$o['current_total'],2,',','.')?> €</strong></a><?php endforeach;?><?php if(!$orders):?><div class="empty">Keine Aufträge.</div><?php endif;?></div>
<h2>Verstöße</h2><div class="worklist"><?php foreach($violations as $v):?><div class="work-row"><div><b>#<?=App\Core\View::e($v['order_number'])?> · <?=App\Core\View::e($v['violation_type'])?></b><span><?=App\Core\View::e($v['description'])?></span></div><strong><?=App\Core\View::e($v['status'])?></strong></div><?php endforeach;?><?php if(!$violations):?><div class="empty">Keine Verstöße.</div><?php endif;?></div>
<h2>Datenänderungen</h2><div class="worklist"><?php foreach($changes as $x):?><div class="work-row"><div><b><?=App\Core\View::e($x['field_name'])?></b><span><?=date('d.m.Y H:i',strtotime($x['changed_at']))?></span></div><small><?=App\Core\View::e($x['old_value'])?> → <?=App\Core\View::e($x['new_value'])?></small></div><?php endforeach;?><?php if(!$changes):?><div class="empty">Keine Änderungen protokolliert.</div><?php endif;?></div>
<h2>Systemereignisse</h2><div class="worklist"><?php foreach($events as $e):?><div class="work-row"><div><b><?=App\Core\View::e($e['event_type'])?></b><span><?=date('d.m.Y H:i',strtotime($e['created_at']))?> · <?=App\Core\View::e($e['actor_type'])?></span></div></div><?php endforeach;?></div>
<?php if(!$seller['deleted_at']):?><section class="danger-zone card"><h2>Konto löschen/anonymisieren</h2><p>Personenbezogene Profildaten werden anonymisiert. Erforderliche Geschäfts-, Zahlungs-, Auftrags- und Nachweisdaten bleiben erhalten.</p><form method="post" action="/admin/verkaeuferinnen/<?=$seller['id']?>/loeschen"><?=App\Core\Csrf::field()?><button class="btn" data-confirm="Konto wirklich löschen und anonymisieren?">Konto löschen/anonymisieren</button></form></section><?php endif;?></main>